//! Attribute macros shared by the hax test suites.
//!
//! `#[hax_test::equiv]` marks a semantic oracle: a `pub fn <name>() -> bool`
//! whose result is asserted on both sides of a translation. The Rust half is
//! a `#[test]` generated by the macro, so `cargo test` on the crate reports a
//! function that returns `false` before any backend runs. The backend half is
//! generated by the test driver from the same declaration, for Lean as a
//! `#guard <name> == .ok true` line.
//!
//! `#[hax_test::equiv(skip_lean = "reason")]` exists for the core-models
//! equivalence tests, whose Lean side is generated by a separate script; the
//! FLS suite rejects it and records the pipeline stage instead.

use proc_macro::TokenStream;
use quote::{format_ident, quote};
use syn::{
    Error, FnArg, ItemFn, LitStr, Result, ReturnType, Token, Type, Visibility, parse::Parse,
    parse::ParseStream, spanned::Spanned,
};

/// The attribute arguments; `skip_lean` is validated and otherwise ignored here.
struct Args;

impl Parse for Args {
    fn parse(input: ParseStream) -> Result<Self> {
        if input.is_empty() {
            return Ok(Args);
        }
        let key: syn::Ident = input.parse()?;
        if key != "skip_lean" {
            return Err(Error::new(
                key.span(),
                "unknown argument; the accepted forms are `#[hax_test::equiv]` and `#[hax_test::equiv(skip_lean = \"reason\")]`",
            ));
        }
        input.parse::<Token![=]>()?;
        let reason: LitStr = input.parse()?;
        if reason.value().trim().is_empty() {
            return Err(Error::new(reason.span(), "skip_lean needs a reason"));
        }
        if !input.is_empty() {
            return Err(input.error("unexpected tokens after `skip_lean = \"...\"`"));
        }
        Ok(Args)
    }
}

fn check(item: &ItemFn) -> Result<()> {
    let sig = &item.sig;
    let err = |span: proc_macro2::Span, msg: &str| Err(Error::new(span, format!("#[hax_test::equiv] {msg}")));
    if let Some(receiver) = sig.inputs.iter().find_map(|arg| match arg {
        FnArg::Receiver(r) => Some(r),
        FnArg::Typed(_) => None,
    }) {
        return err(receiver.span(), "applies to a free function, not a method");
    }
    if let Some(arg) = sig.inputs.first() {
        return err(arg.span(), "takes no parameters");
    }
    if !sig.generics.params.is_empty() || sig.generics.where_clause.is_some() {
        return err(sig.generics.span(), "must not be generic");
    }
    let returns_bool = match &sig.output {
        ReturnType::Type(_, ty) => match &**ty {
            Type::Path(path) => path.qself.is_none() && path.path.is_ident("bool"),
            _ => false,
        },
        ReturnType::Default => false,
    };
    if !returns_bool {
        return err(sig.output.span(), "must return bool");
    }
    if !matches!(item.vis, Visibility::Public(_)) {
        return err(
            sig.ident.span(),
            "must be pub, so that the backend extracts it and the driver finds it",
        );
    }
    if let Some(token) = sig
        .asyncness
        .map(|t| t.span())
        .or(sig.constness.map(|t| t.span()))
        .or(sig.unsafety.map(|t| t.span()))
    {
        return err(token, "must be a plain fn");
    }
    Ok(())
}

/// Marks a `pub fn <name>() -> bool` as a semantic oracle; see the crate documentation.
#[proc_macro_attribute]
pub fn equiv(args: TokenStream, item: TokenStream) -> TokenStream {
    let Args = parse_macro_input!(args as Args);
    let item = match syn::parse::<ItemFn>(item) {
        Ok(item) => item,
        Err(_) => {
            return Error::new(
                proc_macro2::Span::call_site(),
                "#[hax_test::equiv] applies to a free function",
            )
            .to_compile_error()
            .into();
        }
    };
    if let Err(e) = check(&item) {
        return e.to_compile_error().into();
    }
    let name = &item.sig.ident;
    let test_name = format_ident!("__hax_test_equiv_{}", name);
    let message = format!("equiv function `{name}` returned false");
    quote! {
        #item

        #[cfg(test)]
        #[test]
        #[allow(non_snake_case)]
        fn #test_name() {
            assert!(#name(), #message);
        }
    }
    .into()
}
